INSERT INTO tasks(lesson_id, title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy, is_published)
SELECT lr.lesson_id, ts.title, ts.statement_md, ts.starter_code, ts.solution_code, ts.difficulty, ts.xp_reward, ts.topic, ts.language, ts.source_policy, TRUE
FROM lesson_ref lr
CROSS JOIN task_seed ts
ON CONFLICT (lesson_id, title) DO UPDATE
SET statement_md = EXCLUDED.statement_md,
    starter_code = EXCLUDED.starter_code,
    solution_code = EXCLUDED.solution_code,
    difficulty = EXCLUDED.difficulty,
    xp_reward = EXCLUDED.xp_reward,
    topic = EXCLUDED.topic,
    language = EXCLUDED.language,
    source_policy = EXCLUDED.source_policy,
    is_published = TRUE,
    updated_at = NOW();

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 2 AND l.position = 22
)
DELETE FROM task_test_cases tc
USING tasks t, lesson_ref lr
WHERE tc.task_id = t.id
  AND t.lesson_id = lr.lesson_id
  AND t.is_published = TRUE;
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 2 AND l.position = 22
), task_ref AS (
  SELECT t.id AS task_id, t.title
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
  WHERE t.is_published = TRUE
), block_seed(position, block_type, title, content_md, task_title, quiz_payload) AS (
  VALUES
  (1, $m2_l22_b1_type$theory$m2_l22_b1_type$, $m2_l22_b1_title$Смысл$m2_l22_b1_title$, $m2_l22_b1_content$**Коротко:** разберись с темой `pytest: mocking` через маленький рабочий пример.

### Простое объяснение
`pytest: mocking` нужен, чтобы проверять поведение кода до ручного запуска всей программы. Начинай с минимального сценария, который можно запустить и проверить сразу.

### Минимальный пример
```python
def add(a, b):
    return a + b

def test_add():
    assert add(2, 3) == 5
```

### Что здесь важно
Один тест должен проверять одну идею: нормальный сценарий, крайний случай или ошибку.

### Частая ошибка
Тест, который повторяет реализацию, не ловит дефект. Проверяй поведение, а не внутренние строки кода.

### Быстрая самопроверка
Назови действие, которое выполняет пример, и один случай, где он может сломаться.$m2_l22_b1_content$, NULL, NULL::jsonb),
