INSERT INTO lessons(module_id, title, content_md, position, is_published)
SELECT mr.module_id, ls.title, ls.content_md, ls.position, TRUE
FROM module_ref mr
CROSS JOIN lesson_seed ls
ON CONFLICT (module_id, position) DO UPDATE
SET title = EXCLUDED.title,
    content_md = EXCLUDED.content_md,
    is_published = TRUE,
    updated_at = NOW();

-- m4_l1: FastAPI: старт API
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
)
UPDATE lesson_blocks lb
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE lb.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
), task_seed(title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy) AS (
  VALUES
  ($m4_l1_t2_title$GET /tasks$m4_l1_t2_title$, $m4_l1_t2_stmt$**Коротко:** реализуй HTTP-поведение для `FastAPI: старт API`.

### Условие
Добавь endpoint для учебного сервиса задач. Этот шаг тренирует: добавить endpoint, проверить статус и вернуть JSON без лишних полей.

### Вход
HTTP-запрос с методом, путём и JSON-телом.

### Выход
HTTP-статус и JSON без лишних полей.

### Пример
POST `/tasks` с названием задачи возвращает созданную задачу со статусом `201`.

### Что важно
Разделяй схему входа и схему ответа, явно указывай status code и не глотай ошибку валидации.$m4_l1_t2_stmt$, $m4_l1_t2_starter$from fastapi import FastAPI

app = FastAPI()

# добавь endpoint ниже
$m4_l1_t2_starter$, $m4_l1_t2_solution$from fastapi import FastAPI, status
from pydantic import BaseModel

app = FastAPI()

class TaskIn(BaseModel):
    title: str

@app.post('/tasks', status_code=status.HTTP_201_CREATED)
def create_task(data: TaskIn):
    return {'id': 1, 'title': data.title, 'done': False}

@app.get('/tasks')
def list_tasks():
    return []

@app.get('/health')
def health():
    return {'status': 'ok'}
